1382: static ssize_t _nfsd_copy_file_range(struct nfsd4_copy *copy)
1383: {
1384: 	struct file *dst = copy->nf_dst->nf_file;
1385: 	struct file *src = copy->nf_src->nf_file;
1386: 	ssize_t bytes_copied = 0;
1387: 	size_t bytes_total = copy->cp_count;
1388: 	u64 src_pos = copy->cp_src_pos;
1389: 	u64 dst_pos = copy->cp_dst_pos;
1390: 
1391: 	do {
1392: 		if (kthread_should_stop())
1393: 			break;
1394: 		bytes_copied = nfsd_copy_file_range(src, src_pos, dst, dst_pos,
1395: 						    bytes_total);
1396: 		if (bytes_copied <= 0)
1397: 			break;
1398: 		bytes_total -= bytes_copied;
1399: 		copy->cp_res.wr_bytes_written += bytes_copied;
1400: 		src_pos += bytes_copied;
1401: 		dst_pos += bytes_copied;
1402: 	} while (bytes_total > 0 && !copy->cp_synchronous);
1403: 	return bytes_copied;
1404: }
