187: void nfs_sb_deactive(struct super_block *sb)
188: {
189: 	struct nfs_server *server = NFS_SB(sb);
190: 
191: 	if (atomic_dec_and_test(&server->active))
192: 		deactivate_super(sb);
193: }
194: EXPORT_SYMBOL_GPL(nfs_sb_deactive);
